create table RB_CLIENT_RESTRAINTS (CREATE_TIMESTAMP VARCHAR(26) not null  ,NARRATIVE VARCHAR(600) null  ,LAST_UPD_TIMESTAMP VARCHAR(26) not null  ,START_DATE TIMESTAMP(3) null  ,TRAN_BRANCH VARCHAR(30) null  ,RES_PRIORITY VARCHAR(2) null  ,RESTRAINTS_STATUS VARCHAR(1) null  ,END_DATE TIMESTAMP(3) null  ,RES_SEQ_NO VARCHAR(50) not null  ,USER_ID VARCHAR(30) null  ,SOURCE_TYPE VARCHAR(10) null  ,AUTH_USER_ID VARCHAR(30) null  ,RESTRAINT_TYPE VARCHAR(3) not null  ,TERM VARCHAR(5) null  ,TERM_TYPE VARCHAR(1) null  ,CLIENT_NO VARCHAR(22) not null  ,TRAN_DATE TIMESTAMP(3) null  , primary key(RES_SEQ_NO,CLIENT_NO));